from dataclasses import dataclass      # Optional, date from typing/datetime
@dataclass(frozen=True)
class Interval:
    lo: Optional[date] = None          # None = unbounded
    hi: Optional[date] = None
    lo_closed: bool = True
    hi_closed: bool = False            # half-open by default

    def __contains__(self, v: date) -> bool:
        below = self.lo is not None and (v < self.lo or (v == self.lo and not self.lo_closed))
        above = self.hi is not None and (v > self.hi or (v == self.hi and not self.hi_closed))
        return not (below or above)

